  @Test func testBhvSerializationobject189DeserializeMutuallyRecursiveModels() throws {
    let json = "{\"name\":\"Eng\",\"lead\":{\"name\":\"Ada\",\"department\":{\"name\":\"Core\"}}}"
    let dept = try ObjectSerializer.deserialize(json, as: Department.self)
